// One report catalog. Reference examples belong to the template library.
const rcRows=[
 {id:'ai',title:'近期 AI 行业舆情研判',type:'专题研究',status:'可交付',date:'2026-10-17 15:30',topic:'AI 行业',task:'TASK-104',version:'v1',desc:'发布事实、讨论焦点、来源分歧与证据缺口。'},
 {id:'r1',title:'从闲鱼舆情看网络黑灰产',type:'事件分析',status:'待审核',date:'2026-09-23 16:10',topic:'平台治理',task:'TASK-101',version:'v1',desc:'事件脉络、样本分析与黑灰产专题；统计口径待审核。'},
 {id:'r2',title:'9月23日舆情日报',type:'日报',status:'可交付',date:'2026-09-24 06:30',topic:'综合监测',task:'TASK-098',version:'v1',daily:'d23',desc:'事件回落、治理议题升温与讨论变化。'},
 {id:'r3',title:'9月22日舆情日报',type:'日报',status:'可交付',date:'2026-09-23 06:30',topic:'综合监测',task:'TASK-097',version:'v1',daily:'d22',desc:'热度回落，讨论转向平台治理。'},
 {id:'r5',title:'9月21日舆情日报',type:'日报',status:'可交付',date:'2026-09-22 06:30',topic:'综合监测',task:'TASK-096',version:'v1',daily:'d21',desc:'热点爆发与平台回应。'},
 {id:'r4',title:'315 消费维权季前瞻',type:'专题研究',status:'已归档',date:'2026-09-20 14:00',topic:'消费维权',task:'TASK-090',version:'v1',desc:'历史案例、讨论焦点与后续观察。'}
];
for(const r of rcRows)if(!v4Reports[r.id])v4Reports[r.id]={title:r.title,desc:r.desc,kind:'原版示例'};
const rcState={q:'',type:'全部',status:'全部',period:'30',sort:'new',subscription:null};
const rcEsc=v4Esc;
function rcStatus(s){return `<span class="rc-status ${s==='可交付'?'ready':s==='待审核'?'review':'archived'}">${rcEsc(s)}</span>`;}
function rcList(){const cutoff={'7':'2026-10-10','30':'2026-09-17','all':''}[rcState.period];return rcRows.filter(r=>(!rcState.q||[r.title,r.topic,r.task].join(' ').toLowerCase().includes(rcState.q.toLowerCase()))&&(rcState.type==='全部'||r.type===rcState.type)&&(rcState.status==='全部'||r.status===rcState.status)&&(!cutoff||r.date>=cutoff)).sort((a,b)=>rcState.sort==='new'?b.date.localeCompare(a.date):a.date.localeCompare(b.date));}
function rcRender(){document.getElementById('p-report').innerHTML=`<div class="topbar"><div><h1>报告中心</h1><div class="sub">查找、阅读和使用研究成果</div></div><div class="rc-head-actions"><button class="btn" onclick="rcSubscribe()">订阅更新</button><button class="btn dark" onclick="v4DeepRequest()">＋ 新建研究</button></div></div><div class="rc-summary"><span><b>${rcRows.length}</b> 份报告</span><span><i class="rc-dot green"></i>${rcRows.filter(r=>r.status==='可交付').length} 可交付</span><span><i class="rc-dot amber"></i>${rcRows.filter(r=>r.status==='待审核').length} 待审核</span><span class="rc-demo">演示目录 · 内容与状态均为样例</span></div><div class="rc-catalog"><div class="rc-toolbar"><div class="rc-search"><span>⌕</span><input id="rc-search" aria-label="搜索报告" placeholder="搜索报告名称、主题或任务编号" value="${rcEsc(rcState.q)}"></div><label>时间<select id="rc-period" aria-label="报告时间范围"><option value="7" ${rcState.period==='7'?'selected':''}>最近 7 天</option><option value="30" ${rcState.period==='30'?'selected':''}>最近 30 天</option><option value="all" ${rcState.period==='all'?'selected':''}>全部时间</option></select></label><label>排序<select id="rc-sort" aria-label="报告排序"><option value="new" ${rcState.sort==='new'?'selected':''}>最新生成</option><option value="old" ${rcState.sort==='old'?'selected':''}>最早生成</option></select></label></div><div class="rc-filter-line"><span>类型</span>${['全部','日报','事件分析','专题研究','品牌监测'].map(t=>`<button class="${t===rcState.type?'active':''}" data-rc-type="${t}">${t}</button>`).join('')}</div><div class="rc-filter-line"><span>状态</span>${['全部','待审核','可交付','已归档'].map(t=>`<button class="${t===rcState.status?'active':''}" data-rc-status="${t}">${t}</button>`).join('')}</div><div id="rc-results"></div></div><div class="rc-footer"><span>研究进度和失败记录在研究任务中查看；这里统一管理已经形成的报告。</span><button class="rc-text" onclick="v4Go('tpl')">报告模板与参考样例 ↗</button></div>`;rcResults();}
function rcResults(){const rows=rcList();document.getElementById('rc-results').innerHTML=`<div class="rc-result-count">共 ${rows.length} 份结果</div><div class="v4-scroll-table"><table class="rc-table"><thead><tr><th>报告名称 / 主题</th><th>类型</th><th>状态</th><th>生成时间</th><th>操作</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="rc-title" onclick="rcRead('${r.id}')">${rcEsc(r.title)}</button><div class="rc-meta">${rcEsc(r.topic)} <span>·</span> ${r.task} <span>·</span> ${r.version}</div></td><td><span class="rc-type">${r.type}</span></td><td>${rcStatus(r.status)}</td><td class="rc-date">${r.date}</td><td><div class="rc-row-actions"><button class="btn" onclick="rcRead('${r.id}')">阅读</button><details class="rc-more"><summary>更多 ⋯</summary><div class="rc-menu">${[['追问报告',`v4AskReport('${r.id}')`],['导出报告',`rcExport('${r.id}')`],['查看研究任务',`rcTask('${r.id}')`],['更新研究',`rcUpdate('${r.id}')`],[r.status==='已归档'?'恢复归档':'归档',`rcArchive('${r.id}')`]].map(([t,action])=>`<button onclick="this.closest('details').removeAttribute('open');${action}">${t}</button>`).join('')}</div></details></div></td></tr>`).join('')}</tbody></table></div>${!rows.length?'<div class="rc-empty"><span>⌕</span><h3>没有符合条件的报告</h3><p>试试其他关键词，或清除类型、状态和时间筛选。</p><button class="btn" onclick="rcReset()">清除筛选</button></div>':''}`;}
function rcReset(){Object.assign(rcState,{q:'',type:'全部',status:'全部',period:'all',sort:'new'});rcRender();}
function rcBody(r){if(r.daily&&DAILY[r.daily]){const render=x=>Array.isArray(x)?x.map(render).join(''):`<p>${rcEsc(String(x))}</p>`;return DAILY[r.daily].body.map(([title,body])=>`<section><h2>${rcEsc(title)}</h2>${render(body)}</section>`).join('');}if(r.id==='ai')return `<h2>研究摘要</h2><p>本报告用于演示完整研究成果的阅读、追问与证据关联。实际结论应由冻结证据包生成，当前未连接生产模型和采集后台。</p><h2>研究范围与方法</h2><p>围绕 AI 行业公开发布与平台讨论，区分发布事实、讨论观察与解释性判断；检索覆盖、时间窗与样本口径需要在实际研究中记录。</p><h2>证据与审查</h2><p>当前研究工作台保留示例证据及质量门禁，可通过“查看研究任务”核对。真实数据不足时，不生成虚构总量、比例和趋势。</p><h2>局限与后续研究</h2><p>此处不是已核验的生产报告；更新研究将建立关联草案，不覆盖当前版本。</p>`;return `<h2>研究范围</h2><p>${rcEsc(r.desc)}</p><h2>版本说明</h2><p>保留原版报告示例的标题与追问入口。此历史报告未挂载完整正文和原始证据包，因此不将用户提供的参考 PDF 冒充本报告，也不补造表格与数字。</p><h2>交付要求</h2><p>生产报告须包含研究方法、事件背景、统计底表、图表、分析、结论、缺口及来源附录，并通过数据和引用检查。</p>`;}
function rcRead(id){const r=rcRows.find(x=>x.id===id);if(!r)return;v4Go('report');document.getElementById('p-report').innerHTML=`<div class="rc-detail-top"><button class="btn" onclick="rcRender()">← 报告列表</button><div class="rc-head-actions"><button class="btn" onclick="rcTask('${id}')">查看研究任务</button><button class="btn" onclick="rcExport('${id}')">导出</button><button class="btn dark" onclick="v4AskReport('${id}')">追问报告</button></div></div><article class="rc-document"><div class="rc-document-head"><div class="rc-meta">${r.type} · ${r.topic} · ${r.version}</div><h1>${rcEsc(r.title)}</h1><div class="rc-doc-meta">${rcStatus(r.status)}<span>${r.date}</span><span>关联任务 ${r.task}</span></div></div><div class="rc-detail-note">演示内容，未进行新的真实采集。${r.status==='待审核'?'此版本仍有统计口径待核实，不能作为通过审核的正式成果。':'可交付仅演示业务状态，不代表当前样例已经完成真实核验。'}</div><div class="rc-document-body">${rcBody(r)}</div><div class="rc-evidence-note"><b>来源与数据底表</b><p>日报正文沿用原版界面样例；当前未挂载其真实原文、统计底表与证据附件，不能从这些演示数字推导真实结论。</p><button class="btn" onclick="rcTask('${id}')">查看关联任务与证据</button></div></article>`;}
function rcTask(id){const r=rcRows.find(x=>x.id===id);if(id==='ai'){v4Go('research');return;}v4Modal('关联研究任务',`<h3>${r.task} · ${rcEsc(r.title)}</h3><div class="v4-note">当前历史报告只有目录样例，未挂载该任务的独立过程与证据。不会跳转到另一份 AI 研究冒充本任务。</div><button class="btn dark" onclick="v4CloseModal();rcUpdate('${id}')">基于此主题建立新研究</button>`);}
function rcUpdate(id){const r=rcRows.find(x=>x.id===id);v4DeepRequest();const field=document.querySelector('#v4-deep-form [name="topic"]');if(field)field.value='更新研究：'+r.title;}
function rcArchive(id){const r=rcRows.find(x=>x.id===id);if(r.status==='已归档'){r.status=r.beforeArchive||'可交付';}else{r.beforeArchive=r.status;r.status='已归档';}rcRender();showToast('本页目录状态已更新；刷新后恢复演示数据');}
function rcExport(id){const r=rcRows.find(x=>x.id===id);v4Modal('导出报告',`<h3>${rcEsc(r.title)} · ${r.version}</h3><div class="v4-note">HTML / Markdown 导出当前页面的演示正文，带演示声明，不是完整真实数据报告。PDF 需要成稿导出服务，当前未接入。</div>${r.status==='待审核'?'<div class="v4-note orange">待审核版本将保留待审核标记。</div>':''}<div class="v4-report-actions"><button class="btn" onclick="rcDownload('${id}','html')">导出演示 HTML</button><button class="btn" onclick="rcDownload('${id}','md')">导出演示 Markdown</button><button class="btn" disabled title="需要接入 PDF 导出服务">PDF · 待接入</button></div>`);}
function rcDownload(id,format){const r=rcRows.find(x=>x.id===id),body=rcBody(r),head=`${r.title} · ${r.version} · ${r.status}\n演示内容，非真实采集报告。\n`;const el=document.createElement('div');el.innerHTML=body;const data=format==='html'?`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>${rcEsc(r.title)}</title><style>body{max-width:900px;margin:50px auto;font:16px/1.9 system-ui;padding:20px}h1,h2{color:#303957}</style><h1>${rcEsc(r.title)}</h1><p>${rcEsc(head)}</p>${body}</html>`:'# '+head+'\n'+el.textContent;const url=URL.createObjectURL(new Blob([data],{type:format==='html'?'text/html;charset=utf-8':'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=r.title+'-演示.'+format;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function rcSubscribe(){const s=rcState.subscription;v4Modal('订阅报告更新',`<form id="rc-subscribe-form"><p class="v4-label">按报告类型订阅完成事件，报告入库后通过所选渠道提醒。</p><div class="v4-field"><label>报告类型</label><select name="type">${['全部','日报','事件分析','专题研究','品牌监测'].map(t=>`<option ${s?.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="v4-field"><label>通知渠道</label><select name="channel">${['仅平台内提醒','飞书','企业微信'].map(t=>`<option ${s?.channel===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="v4-note">当前只保存本页订阅草稿，不发消息。生产接入后，报告通过交付检查并入库成功才触发完成通知；渠道配置在定制中心管理。</div><button class="btn dark" type="submit">保存订阅草稿</button></form>`);}
document.addEventListener('input',e=>{if(e.target.id==='rc-search'){rcState.q=e.target.value;rcResults();}});
document.addEventListener('change',e=>{if(e.target.id==='rc-period')rcState.period=e.target.value;else if(e.target.id==='rc-sort')rcState.sort=e.target.value;else return;rcResults();});
document.addEventListener('click',e=>{const b=e.target.closest('[data-rc-type],[data-rc-status]');if(b){if(b.dataset.rcType)rcState.type=b.dataset.rcType;if(b.dataset.rcStatus)rcState.status=b.dataset.rcStatus;rcRender();}});
document.addEventListener('submit',e=>{if(e.target.id!=='rc-subscribe-form')return;e.preventDefault();const d=new FormData(e.target);rcState.subscription={type:String(d.get('type')),channel:String(d.get('channel'))};v4CloseModal();showToast('订阅草稿已保存在本页，未发送通知');});
const rcBeforeGo=v4Go;v4Go=function(id){rcBeforeGo(id);if(id==='report')rcRender();};
// The source PDF is a template reference, never a generated report.
document.getElementById('p-tpl').insertAdjacentHTML('beforeend',`<div class="v4-panel"><div class="v4-between"><div><h3>参考样例 · 完整专题报告</h3><p class="v4-label">用户提供的 15 页样稿，用于参考章节、统计表与版式；不属于本平台已生成成果。</p></div><a class="btn" href="report-benchmark.html" target="_blank" rel="noopener">查看参考样稿 ↗</a></div><button class="btn" onclick="v4Go('deepreport')">查看完整报告交付标准</button></div>`);
rcRender();
